$f = "d:\Ade Wiramiharja\Aplikasi\Media Tools\src\app\page.tsx"
$lines = [System.IO.File]::ReadAllLines($f, [System.Text.Encoding]::UTF8)

$before = $lines[0..1522]
$after  = $lines[1606..($lines.Count - 1)]

$newBlock = @"
`r`n  // Regulasi per pertandingan:`r`n  // - Starting XI : 11 pemain, maks 7 asing`r`n  // - Cadangan    : maks 15 (termasuk asing yang tidak masuk starting)`r`n  // - Total asing di starting + cadangan DSP = maks 9`r`n  // - Non-DSP     : 2 asing input manual (di luar skuad 15)`r`n  const MAX_SUBS        = 15;`r`n  const MAX_ASING_TOTAL =  9;`r`n  const MAX_ASING_ST    =  7;`r`n  const MAX_NONDSP      =  2;`r`n`r`n  const homeValid = homeStarters.length === 11;`r`n  const awayValid = awayStarters.length === 11;`r`n  const homeHasGK = homeSquad.some(p => homeStarters.includes(p.id) && p.position === 'Goalkeeper');`r`n  const awayHasGK = awaySquad.some(p => awayStarters.includes(p.id) && p.position === 'Goalkeeper');`r`n  const posLabel: Record<string, string> = { Goalkeeper: 'GK', Defender: 'DF', Midfielder: 'MF', Forward: 'FW' };`r`n`r`n  const pickPlayer = (`r`n    id: string,`r`n    squad: Player[],`r`n    starters: string[], setStarters: React.Dispatch<React.SetStateAction<string[]>>,`r`n    subs:     string[], setSubs:     React.Dispatch<React.SetStateAction<string[]>>,`r`n    asingList: AsingEntry[], setAsing: React.Dispatch<React.SetStateAction<AsingEntry[]>>`r`n  ) => {`r`n    const player = squad.find(p => p.id === id);`r`n    if (!player) return;`r`n    const isForeign = player.nationality !== 'Indonesia';`r`n`r`n    if (isForeign) {`r`n      const fSt    = squad.filter(p => starters.includes(p.id) && p.nationality !== 'Indonesia').length;`r`n      const fSub   = squad.filter(p => subs.includes(p.id)     && p.nationality !== 'Indonesia').length;`r`n      const fTotal = fSt + fSub;`r`n`r`n      if (fTotal >= MAX_ASING_TOTAL) {`r`n        if (asingList.length < MAX_NONDSP) {`r`n          const entry: AsingEntry = { id: 'nd-' + id, name: player.displayName, no: player.shirtNumber, pos: posLabel[player.position] || 'MF' };`r`n          setAsing(prev => [...prev, entry]);`r`n          triggerToast(player.displayName + ' otomatis masuk Non-DSP - kuota 9 asing DSP penuh', 'warning');`r`n        } else {`r`n          triggerToast('Kuota asing penuh: 9 DSP dan 2 Non-DSP sudah tercapai.', 'warning');`r`n        }`r`n        return;`r`n      }`r`n`r`n      if (starters.length < 11 && fSt < MAX_ASING_ST) {`r`n        setStarters(p => [...p, id]);`r`n      } else if (starters.length < 11 && fSt >= MAX_ASING_ST) {`r`n        if (subs.length < MAX_SUBS) {`r`n          setSubs(p => [...p, id]);`r`n          triggerToast(player.displayName + ' masuk cadangan - maks 7 asing di starting', 'warning');`r`n        } else {`r`n          triggerToast('Cadangan sudah penuh.', 'warning');`r`n        }`r`n      } else {`r`n        if (subs.length < MAX_SUBS) {`r`n          setSubs(p => [...p, id]);`r`n        } else {`r`n          triggerToast('Cadangan sudah penuh.', 'warning');`r`n        }`r`n      }`r`n`r`n    } else {`r`n      if (starters.length < 11) {`r`n        setStarters(p => [...p, id]);`r`n      } else if (subs.length < MAX_SUBS) {`r`n        setSubs(p => [...p, id]);`r`n      } else {`r`n        triggerToast('Cadangan sudah penuh.', 'warning');`r`n      }`r`n    }`r`n  };`r`n`r`n  const returnToPool = (`r`n    id: string,`r`n    starters: string[], setStarters: React.Dispatch<React.SetStateAction<string[]>>,`r`n    subs:     string[], setSubs:     React.Dispatch<React.SetStateAction<string[]>>`r`n  ) => {`r`n    if (starters.includes(id)) setStarters(p => p.filter(x => x !== id));`r`n    else if (subs.includes(id)) setSubs(p => p.filter(x => x !== id));`r`n  };
"@

$midLines = $newBlock -split "`r`n"
$newLines = $before + $midLines + $after
[System.IO.File]::WriteAllLines($f, $newLines, [System.Text.UTF8Encoding]::new($false))
Write-Host "Done. Lines: $($newLines.Count)"
